 171       certifications: prev.certifications.filter(item => item.id !== id)
 172     }))
 173   }
 174 
 175   const addProject = (data: CVState['projects'][0]) => {
 176     setCvData(prev => ({
 177       ...prev,
 178       projects: [...prev.projects, data]
 179     }))
 180   }
 181 
 182   const updateProject = (id: string, data: Partial<CVState['projects'][0]>) => {
 183     setCvData(prev => ({
 184       ...prev,
 185       projects: prev.projects.map(item =>
 186         item.id === id ? { ...item, ...data } : item
 187       )
 188     }))
 189   }
 190 
 191   const deleteProject = (id: string) => {
 192     setCvData(prev => ({
 193       ...prev,
 194       projects: prev.projects.filter(item => item.id !== id)
 195     }))
 196   }
