 198   const addLanguage = (data: CVState['languages'][0]) => {
 199     setCvData(prev => ({
 200       ...prev,
 201       languages: [...prev.languages, data]
 202     }))
 203   }
 204 
 205   const updateLanguage = (id: string, data: Partial<CVState['languages'][0]>) => {
 206     setCvData(prev => ({
 207       ...prev,
 208       languages: prev.languages.map(item =>
 209         item.id === id ? { ...item, ...data } : item
 210       )
 211     }))
 212   }
 213 
 214   const deleteLanguage = (id: string) => {
 215     setCvData(prev => ({
 216       ...prev,
 217       languages: prev.languages.filter(item => item.id !== id)
 218     }))
 219   }
 220 
 221   const setTemplate = (template: TemplateType) => {
 222     setCvData(prev => ({ ...prev, selectedTemplate: template }))
 223   }
 224 
 225   const resetCV = () => {
 226     setCvData(getInitialCVState())
 227   }
 228 
 229   // Profile management functions
 230   const refreshProfiles = () => {
 231     setProfiles(getProfilesMetadata())
 232   }
 233 
 234   const createNewProfile = (name: string) => {
 235     const newProfile = createProfile(name)
 236     setCurrentProfile(newProfile)
 237     setCvData(newProfile.cvData)
 238     refreshProfiles()
 239   }
 240 
 241   const switchProfile = (profileId: string) => {
 242     setActiveProfileId(profileId)
 243     const profile = getActiveProfile()
 244     if (profile) {
 245       setCurrentProfile(profile)
 246       setCvData(profile.cvData)
 247     }
 248   }
 249 
 250   const deleteCurrentProfile = (profileId: string) => {
 251     deleteProfile(profileId)
 252     const profile = getActiveProfile()
 253     if (profile) {
 254       setCurrentProfile(profile)
 255       setCvData(profile.cvData)
 256     } else {
 257       // No profiles left, create a new one
 258       createNewProfile('My CV')
 259     }
 260     refreshProfiles()
 261   }
 262 
 263   const renameCurrentProfile = (profileId: string, newName: string) => {
 264     renameProfile(profileId, newName)
 265     const profile = getActiveProfile()
 266     if (profile) {
 267       setCurrentProfile(profile)
 268     }
 269     refreshProfiles()
 270   }
 271 
 272   const duplicateCurrentProfile = (profileId: string) => {
 273     const newProfile = duplicateProfile(profileId)
 274     if (newProfile) {
 275       setActiveProfileId(newProfile.id)
 276       setCurrentProfile(newProfile)
 277       setCvData(newProfile.cvData)
 278       refreshProfiles()
 279     }
 280   }
 281 
 282   const exportProfile = (profileId: string) => {
 283     const profile = getActiveProfile()
 284     if (profile && profile.id === profileId) {
 285       exportProfileAsJSON(profile)
 286     }
 287   }
 288 
 289   const importProfile = (jsonData: string) => {
 290     const newProfile = importProfileFromJSON(jsonData)
 291     if (newProfile) {
 292       setActiveProfileId(newProfile.id)
 293       setCurrentProfile(newProfile)
 294       setCvData(newProfile.cvData)
 295       refreshProfiles()
 296     }
 297   }
