 299   const importFromLinkedIn = (data: Partial<CVData>) => {
 300     setCvData(prev => ({
 301       ...prev,
 302       personalInfo: data.personalInfo ? { ...prev.personalInfo, ...data.personalInfo } : prev.personalInfo,
 303       workExperience: data.workExperience ? [...data.workExperience, ...prev.workExperience] : prev.workExperience,
 304       education: data.education ? [...data.education, ...prev.education] : prev.education,
 305       skills: data.skills ? [...data.skills, ...prev.skills] : prev.skills,
 306       certifications: data.certifications ? [...data.certifications, ...prev.certifications] : prev.certifications,
 307       projects: data.projects ? [...data.projects, ...prev.projects] : prev.projects,
 308       languages: data.languages ? [...data.languages, ...prev.languages] : prev.languages,
 309     }))
 310   }
 311 
 312   return (
 313     <CVContext.Provider
 314       value={{
 315         cvData,
 316         currentProfile,
 317         profiles,
 318         updatePersonalInfo,
 319         addWorkExperience,
 320         updateWorkExperience,
 321         deleteWorkExperience,
 322         addEducation,
 323         updateEducation,
 324         deleteEducation,
 325         addSkill,
 326         updateSkill,
 327         deleteSkill,
 328         addCertification,
 329         updateCertification,
 330         deleteCertification,
 331         addProject,
 332         updateProject,
 333         deleteProject,
 334         addLanguage,
 335         updateLanguage,
 336         deleteLanguage,
 337         setTemplate,
 338         resetCV,
 339         createNewProfile,
 340         switchProfile,
 341         deleteCurrentProfile,
 342         renameCurrentProfile,
 343         duplicateCurrentProfile,
 344         exportProfile,
 345         importProfile,
 346         importFromLinkedIn,
 347         refreshProfiles,
 348       }}
 349     >
 350       {children}
 351     </CVContext.Provider>
 352   )
 353 }
